const $=s=>document.querySelector(s);const $$=(s,root)=>Array.from((root||document).querySelectorAll(s));
const app=$('#app');
const state={me:null,data:null,page:'dashboard',dark:localStorage.getItem('dm-theme')==='dark',branding:null,filter:''};
if(state.dark)document.body.classList.add('dark');
const money=n=>new Intl.NumberFormat('sq-AL',{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(Number(n)||0);
const money2=n=>new Intl.NumberFormat('sq-AL',{style:'currency',currency:'EUR',minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(n)||0);
const esc=s=>String(s==null?'':s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmtDate=d=>{if(!d)return '—';const x=new Date(d);return isNaN(x)?'—':x.toLocaleDateString('sq-AL',{day:'2-digit',month:'2-digit',year:'numeric'});};
const today=()=>new Date().toISOString().slice(0,10);
const qp=k=>new URLSearchParams(location.search).get(k);
const slugify=s=>(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'');
async function api(path,opts={}){const r=await fetch('/api'+path,{headers:{'Content-Type':'application/json'},...opts});if(!r.ok){let e='Gabim në server';try{e=(await r.json()).error||e;}catch{}throw new Error(e);}try{return await r.json();}catch{return{};}}
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(t._t);t._t=setTimeout(()=>t.classList.remove('show'),2800);}
function openModal(html,wide){const m=$('#modal');m.innerHTML=`<div class="modal${wide?' wide':''}">${html}</div>`;m.classList.remove('hidden');m.onclick=e=>{if(e.target===m)closeModal();};}
function closeModal(){const m=$('#modal');m.classList.add('hidden');m.innerHTML='';}
const roleName=r=>({SUPER_ADMIN:'Superadministrator',COMPANY_ADMIN:'Administrator firme',WORKER:'Punëtor'}[r]||r);
const statusBadge=s=>{const c=s==='Paguar'?'ok':s==='Pjesërisht'?'warn':'bad';return `<span class="badge ${c}">${esc(s)}</span>`;};
function icon(n){const m={dashboard:'▤',sales:'🛒',clients:'👥',payments:'💳',invoices:'🧾',operators:'🤝',expenses:'💸',reports:'📈',workers:'👷',audit:'🕒',companies:'🏢'};return m[n]||'•';}

/* ---------------- LOGIN ---------------- */
function renderLogin(){
 const b=state.branding&&state.branding.company;
 const firmName=b?(state.branding.company.displayName||state.branding.company.name):null;
 const host=b?`${state.branding.subdomain}.datapos.pro`:null;
 app.innerHTML=`<main class="login-shell"><section class="login-brand">
  <img class="hero" src="/hero.jpg" alt="">
  <div class="veil"></div>
  <div class="brand-word">DataManagment</div>
  <div class="login-copy">
   <span class="eyebrow">Kontroll financiar për agjenci turistike</span>
   <h1>Menaxho shitjet, pagesat, faturat dhe fitimin — në një vend të vet.</h1>
   <p>DataManagment ju jep pasqyrë të qartë: sa keni shitur, sa keni arkëtuar, sa ju detyrohen klientët dhe sa u detyroheni operatorëve — në kohë reale.</p>
   <ul class="value-list">
    <li><span class="vi">€</span><div><strong>Të ardhurat &amp; fitimi real</strong><span>Fitimi për çdo rezervim dhe muaj</span></div></li>
    <li><span class="vi">⇄</span><div><strong>Borxhe &amp; pagesa me këste</strong><span>Klientë dhe operatorë në kontroll</span></div></li>
    <li><span class="vi">🧾</span><div><strong>Fatura me TVSH &amp; PDF</strong><span>Gjenero, shkarko dhe printo fatura</span></div></li>
   </ul>
  </div>
  <div class="brand-foot"><span>© 2026 DataManagment</span><span>datapos.pro</span></div>
 </section>
 <section class="login-form-wrap"><form class="login-card" id="loginForm">
  ${firmName?`<div class="firm-badge">${esc(firmName)} • ${esc(host)}</div>`:'<div class="firm-badge muted">Platformë financiare</div>'}
  <h2>${firmName?`Hyrje për ${esc(firmName)}`:'Hyrje në platformë'}</h2>
  <p class="sub">Vendosni kredencialet tuaja për të aksesuar panelin.</p>
  <div id="loginError"></div>
  <div class="field"><label for="username">Emri i përdoruesit</label><input class="input" id="username" name="username" autocomplete="username" placeholder="Përdoruesi juaj" required></div>
  <div class="field"><label for="password">Fjalëkalimi</label><div class="input-wrap"><input class="input" id="password" name="password" type="password" autocomplete="current-password" placeholder="Fjalëkalimi juaj" required><button class="toggle" type="button" id="togglePw">Shfaq</button></div></div>
  <div class="row-between"><label class="check"><input type="checkbox" name="remember"> Më mbaj të kyçur</label><button type="button" class="link" id="forgot">Harruat fjalëkalimin?</button></div>
  <button class="btn btn-primary btn-block" type="submit">Kyçu</button>
  <div class="secured"><span class="dot"></span> Lidhje e siguruar • sesione të enkriptuara</div>
 </form></section></main>`;
 $('#loginForm').onsubmit=login;
 $('#togglePw').onclick=e=>{const p=$('#password');const on=p.type==='password';p.type=on?'text':'password';e.target.textContent=on?'Fsheh':'Shfaq';};
 $('#forgot').onclick=()=>toast('Kontaktoni administratorin e firmës për rivendosjen e fjalëkalimit.');
}
async function login(e){e.preventDefault();const btn=e.target.querySelector('button[type=submit]');btn.disabled=true;btn.textContent='Duke u kyçur…';try{const fd=new FormData(e.target);const d=await api('/login',{method:'POST',body:JSON.stringify({username:fd.get('username'),password:fd.get('password')})});state.me=d.user;await load();}catch(x){$('#loginError').innerHTML=`<div class="error">${esc(x.message)}</div>`;btn.disabled=false;btn.textContent='Kyçu';}}
async function load(){state.data=await api('/dashboard');renderShell();}

/* ---------------- SHELL ---------------- */
function navItems(){return state.me.role==='SUPER_ADMIN'?[['dashboard','Pasqyra'],['companies','Firmat'],['audit','Historiku']]:[['dashboard','Dashboard'],['sales','Shitjet'],['clients','Klientët'],['payments','Pagesat'],['invoices','Fatura'],['operators','Operatorët'],['expenses','Shpenzimet'],['reports','Raportet'],...(state.me.role==='COMPANY_ADMIN'?[['workers','Punëtorët']]:[]),['audit','Historiku']];}
function mobilePrimary(){var all=navItems();var pick=function(){var ps=[].slice.call(arguments);return ps.map(function(p){return all.find(function(x){return x[0]===p;});}).filter(Boolean);};var items=state.me.role==='SUPER_ADMIN'?pick('dashboard','companies','audit'):pick('dashboard','sales','payments','invoices');return items.slice(0,4);}
function mobileNavHtml(){var items=mobilePrimary();var half=Math.ceil(items.length/2);var left=items.slice(0,half),right=items.slice(half);var btn=function(it){var p=it[0],l=it[1];return '<button class="mnav-item '+(state.page===p?'active':'')+'" data-mpage="'+p+'"><span class="mnav-ic">'+icon(p)+'</span><span class="mnav-lbl">'+l+'</span></button>';};return '<nav class="mobilenav" aria-label="Navigim"><div class="mnav-bar"><div class="mnav-side">'+left.map(btn).join('')+'</div><button class="mnav-center" id="mnavMenu" aria-label="Menuja">☰</button><div class="mnav-side">'+right.map(btn).join('')+'</div></div></nav>';}
function renderShell(){
 const d=state.data;const cname=d.company?esc(d.company.displayName||d.company.name):(state.me.role==='SUPER_ADMIN'?'DataManagment':'');
 app.innerHTML=`<div class="app-shell"><aside class="sidebar" id="sidebar">
  <div class="side-brand">DataManagment</div>
  <div class="nav-label">Menuja kryesore</div>
  <nav class="nav">${navItems().map(([p,l])=>`<button data-page="${p}" class="${state.page===p?'active':''}"><span class="nav-icon">${icon(p)}</span>${l}</button>`).join('')}</nav>
  <div class="sidebar-footer">${state.me.role==='SUPER_ADMIN'?'Administrim i platformës':cname||'Sistem financiar'}</div>
 </aside>
 <section class="main"><header class="topbar">
  <div class="top-left"><button class="icon-btn mobile-menu" id="menuBtn">☰</button><span class="page-title" id="pageTitle"></span></div>
  <div class="top-actions"><button class="icon-btn" id="themeBtn" title="Ndrysho temën">${state.dark?'☀':'☾'}</button><div class="user-pill"><span class="avatar">${state.me.name.split(' ').map(x=>x[0]).slice(0,2).join('')}</span><div class="user-meta"><strong>${esc(state.me.name)}</strong><span>${roleName(state.me.role)}</span></div></div><button class="btn btn-secondary" id="logoutBtn">Dil</button></div>
 </header><div class="content" id="content"></div></section><div class="nav-scrim" id="navScrim"></div>${mobileNavHtml()}</div><div class="modal-backdrop hidden" id="modal"></div>`;
 $$('[data-page]').forEach(b=>b.onclick=()=>{state.page=b.dataset.page;state.filter='';$('#sidebar').classList.remove('open');document.body.classList.remove('nav-open');renderShell();});
 var openNav=function(o){var s=$('#sidebar');var on=o==null?!s.classList.contains('open'):o;s.classList.toggle('open',on);document.body.classList.toggle('nav-open',on);};$('#menuBtn').onclick=function(){openNav();};var _mm=$('#mnavMenu');if(_mm)_mm.onclick=function(){openNav();};var _sc=$('#navScrim');if(_sc)_sc.onclick=function(){openNav(false);};$('[data-mpage]').forEach(function(b){b.onclick=function(){state.page=b.dataset.mpage;state.filter='';openNav(false);renderShell();};});
 $('#themeBtn').onclick=()=>{state.dark=!state.dark;document.body.classList.toggle('dark',state.dark);localStorage.setItem('dm-theme',state.dark?'dark':'light');renderShell();};
 $('#logoutBtn').onclick=async()=>{await api('/logout',{method:'POST'});state.me=null;renderLogin();};
 renderPage();
}
function renderPage(){const c=$('#content');const titles={dashboard:'Dashboard',sales:'Menaxhimi i shitjeve',clients:'Klientët',payments:'Pagesat',invoices:'Fatura',operators:'Operatorët',expenses:'Shpenzimet',reports:'Raportet',workers:'Punëtorët',audit:'Historiku',companies:'Firmat'};
 $('#pageTitle').textContent=state.me.role==='SUPER_ADMIN'?(state.page==='dashboard'?'Pasqyra e platformës':titles[state.page]):titles[state.page]||'';
 if(state.me.role==='SUPER_ADMIN')return ({dashboard:superDash,companies:superCompanies,audit:auditPage}[state.page]||superDash)(c);
 ({dashboard,sales,clients,payments,invoices,operators,expenses,reports,workers,audit:auditPage}[state.page]||dashboard)(c);}
function heading(title,desc,actions=''){return `<div class="heading-row"><div><h1>${title}</h1><p class="muted">${desc}</p></div><div class="actions">${actions}</div></div>`;}
function kpi(label,val,sub,tone){return `<article class="kpi ${tone||''}"><div class="kpi-label">${label}</div><div class="kpi-val">${val}</div>${sub?`<div class="kpi-sub">${sub}</div>`:''}</article>`;}

/* ---------------- DASHBOARD ---------------- */
function dashboard(c){const d=state.data;const k=d.kpis;
 const byMonth={};d.sales.forEach(s=>{const mth=(s.travelDate||s.bookingDate||'').slice(0,7);if(!mth)return;byMonth[mth]=byMonth[mth]||{sales:0,profit:0};byMonth[mth].sales+=s.sellingPrice;byMonth[mth].profit+=s.profit;});
 const months=Object.keys(byMonth).sort().slice(-6);
 const dest={};d.sales.forEach(s=>{dest[s.destination]=(dest[s.destination]||0)+s.sellingPrice;});
 const topDest=Object.entries(dest).sort((a,b)=>b[1]-a[1]).slice(0,5);
 c.innerHTML=heading('Dashboard','Pasqyrë financiare në kohë reale.','')
 +`<section class="kpis">
  ${kpi('Shitje totale',money(k.totalSales),d.sales.length+' rezervime')}
  ${kpi('Fitimi bruto',money(k.profit),'Marzha '+(k.totalSales?Math.round(k.profit/k.totalSales*100):0)+'%','tone-green')}
  ${kpi('Arkëtuar',money(k.received),'nga klientët')}
  ${kpi('Borxhe klientësh',money(k.clientDebt),'për t’u arkëtuar','tone-amber')}
  ${kpi('Detyrime operatorësh',money(k.operatorDebt),'për t’u paguar','tone-red')}
  ${kpi('Shpenzime',money(k.expenses),'operative')}
  ${kpi('Fitimi neto',money(k.netProfit),'pas shpenzimeve','tone-green')}
  ${kpi('Klientë',k.clients,'aktivë')}
 </section>
 <section class="grid-2">
  <article class="card"><div class="card-head"><h3>Shitjet & fitimi — 6 muajt e fundit</h3></div>${barChart(months.map(m=>({label:m.slice(5),a:byMonth[m].sales,b:byMonth[m].profit})))}<div class="legend"><span><i class="sw blue"></i>Shitje</span><span><i class="sw green"></i>Fitim</span></div></article>
  <article class="card"><div class="card-head"><h3>Top destinacionet</h3></div>${rankList(topDest.map(([n,v])=>({name:n,val:v})),topDest[0]?topDest[0][1]:1)}</article>
 </section>
 <article class="card"><div class="card-head"><h3>Shitjet e fundit</h3><button class="btn btn-secondary sm" id="toSales">Shiko të gjitha</button></div>
  <div class="table-wrap"><table><thead><tr><th>Booking</th><th>Klienti</th><th>Destinacioni</th><th>Data e udhëtimit</th><th class="num">Çmimi</th><th class="num">Borxh</th><th>Statusi</th></tr></thead><tbody>${d.sales.slice(0,6).map(s=>`<tr><td class="mono">${esc(s.bookingId)}</td><td>${esc(s.clientName)}</td><td>${esc(s.destination)}</td><td>${fmtDate(s.travelDate)}</td><td class="num">${money(s.sellingPrice)}</td><td class="num">${money(s.clientDebt)}</td><td>${statusBadge(s.paymentStatus)}</td></tr>`).join('')}</tbody></table></div></article>`;
 $('#toSales').onclick=()=>{state.page='sales';renderShell();};
}
function barChart(rows){if(!rows.length)return '<div class="empty">Nuk ka të dhëna.</div>';const max=Math.max(1,...rows.map(r=>Math.max(r.a,r.b)));const W=560,H=200,bw=W/rows.length;let bars='';rows.forEach((r,i)=>{const x=i*bw+bw*0.18;const w=bw*0.28;const ha=r.a/max*(H-30),hb=r.b/max*(H-30);bars+=`<rect x="${x}" y="${H-ha-20}" width="${w}" height="${ha}" rx="4" fill="#2563eb"></rect><rect x="${x+w+4}" y="${H-hb-20}" width="${w}" height="${hb}" rx="4" fill="#178a57"></rect><text x="${x+w}" y="${H-4}" text-anchor="middle" class="axl">${esc(r.label)}</text>`;});return `<svg viewBox="0 0 ${W} ${H}" class="chart" preserveAspectRatio="xMidYMid meet">${bars}</svg>`;}
function rankList(rows,max){if(!rows.length)return '<div class="empty">Nuk ka të dhëna.</div>';return '<div class="ranks">'+rows.map(r=>`<div class="rank"><div class="rank-top"><span>${esc(r.name)}</span><strong>${money(r.val)}</strong></div><div class="bar"><i style="width:${Math.max(4,r.val/max*100)}%"></i></div></div>`).join('')+'</div>';}

/* ---------------- SALES ---------------- */
function sales(c){const d=state.data;const f=(state.filter||'').toLowerCase();
 let rows=d.sales.filter(s=>!f||[s.bookingId,s.clientName,s.destination,s.operatorName,s.hotel].join(' ').toLowerCase().includes(f));
 if(state.salesStatus)rows=rows.filter(s=>s.paymentStatus===state.salesStatus);
 c.innerHTML=heading('Menaxhimi i shitjeve','Lista e paketave, klientëve, pagesave, borxheve dhe fitimit.',`<button class="btn btn-secondary" id="expCsv">⤓ Eksporto CSV</button><button class="btn btn-primary" id="newSale">+ Shitje e re</button>`)
 +`<div class="toolbar"><input class="input search" id="q" placeholder="Kërko sipas klientit, booking-ut ose destinacionit…" value="${esc(state.filter||'')}"><select class="input" id="fStatus" style="max-width:180px"><option value="">Të gjitha statuset</option>${['Paguar','Pjesërisht','Pa paguar'].map(s=>`<option ${state.salesStatus===s?'selected':''}>${s}</option>`).join('')}</select><span class="count">${rows.length} rezultate</span></div>
 <div class="card"><div class="table-wrap"><table><thead><tr><th>Booking</th><th>Klienti</th><th>Destinacioni</th><th>Operatori</th><th>Udhëtimi</th><th>Kthimi</th><th class="num">Çmimi</th><th class="num">Paguar</th><th class="num">Borxh</th><th class="num">Fitim</th><th>Statusi</th><th class="ta-r">Veprime</th></tr></thead><tbody>
 ${rows.map(s=>`<tr><td class="mono">${esc(s.bookingId)}</td><td>${esc(s.clientName)}</td><td>${esc(s.destination)}<div class="sub">${esc(s.hotel||'')}</div></td><td>${esc(s.operatorName)}</td><td>${fmtDate(s.travelDate)}</td><td>${fmtDate(s.returnDate)}</td><td class="num">${money(s.sellingPrice)}</td><td class="num">${money(s.clientPaid)}</td><td class="num ${s.clientDebt>0?'neg':''}">${money(s.clientDebt)}</td><td class="num pos">${money(s.profit)}</td><td>${statusBadge(s.paymentStatus)}</td><td class="ta-r"><div class="rowbtns"><button class="mini" data-pay="${s.id}" title="Pagesë">€</button><button class="mini" data-inv="${s.id}" title="Faturë">🧾</button><button class="mini" data-edit="${s.id}" title="Edito">✎</button><button class="mini danger" data-del="${s.id}" title="Fshi">✕</button></div></td></tr>`).join('')||`<tr><td colspan="12" class="empty">Nuk ka shitje.</td></tr>`}
 </tbody></table></div></div>`;
 $('#newSale').onclick=()=>saleModal();
 $('#expCsv').onclick=()=>exportCsv(rows);
 $('#q').oninput=e=>{state.filter=e.target.value;const cur=e.target.selectionStart;sales(c);const q=$('#q');q.focus();q.setSelectionRange(cur,cur);};
 $('#fStatus').onchange=e=>{state.salesStatus=e.target.value;sales(c);};
 $$('[data-edit]').forEach(b=>b.onclick=()=>saleModal(d.sales.find(s=>s.id===b.dataset.edit)));
 $$('[data-del]').forEach(b=>b.onclick=()=>confirmDel('Këtë shitje',async()=>{await api('/sales/'+b.dataset.del,{method:'DELETE'});toast('Shitja u fshi.');await load();}));
 $$('[data-pay]').forEach(b=>b.onclick=()=>paymentModal(d.sales.find(s=>s.id===b.dataset.pay)));
 $$('[data-inv]').forEach(b=>b.onclick=()=>{const s=d.sales.find(x=>x.id===b.dataset.inv);invoiceModal(null,s);});
}
function clientOperatorPickers(sel){const d=state.data;
 return `<div class="field"><label>Klienti</label><select class="input" id="clientSel">${d.clients.map(c=>`<option value="${c.id}" ${sel&&sel.clientId===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}<option value="__new__">➕ Shto klient të ri…</option></select>
  <div id="newClientBox" class="subform hidden"><div class="grid-2"><input class="input" id="ncName" placeholder="Emri i klientit *"><input class="input" id="ncPhone" placeholder="Telefoni"></div><div class="grid-2"><input class="input" id="ncEmail" placeholder="Email"><input class="input" id="ncAddr" placeholder="Adresa"></div></div></div>
  <div class="field"><label>Operatori</label><select class="input" id="operSel">${d.operators.map(o=>`<option value="${o.id}" ${sel&&sel.operatorId===o.id?'selected':''}>${esc(o.name)}</option>`).join('')}<option value="__new__">➕ Shto operator të ri…</option></select>
  <div id="newOperBox" class="subform hidden"><div class="grid-2"><input class="input" id="noName" placeholder="Emri i operatorit *"><input class="input" id="noPhone" placeholder="Telefoni"></div><input class="input" id="noEmail" placeholder="Email"></div></div>`;}
function bindPickers(){const cs=$('#clientSel'),ob=$('#newClientBox'),os=$('#operSel'),nb=$('#newOperBox');
 const t=()=>{ob.classList.toggle('hidden',cs.value!=='__new__');nb.classList.toggle('hidden',os.value!=='__new__');};
 cs.onchange=t;os.onchange=t;t();}
function gatherPickers(){const cs=$('#clientSel'),os=$('#operSel');const out={};if(cs.value==='__new__'){const name=$('#ncName').value.trim();if(!name)throw new Error('Shkruani emrin e klientit të ri.');out.newClient={name,phone:$('#ncPhone').value.trim(),email:$('#ncEmail').value.trim(),address:$('#ncAddr').value.trim()};}else out.clientId=cs.value;
 if(os.value==='__new__'){const name=$('#noName').value.trim();if(!name)throw new Error('Shkruani emrin e operatorit të ri.');out.newOperator={name,phone:$('#noPhone').value.trim(),email:$('#noEmail').value.trim()};}else out.operatorId=os.value;return out;}
function saleModal(sale){const edit=!!sale;
 openModal(`<div class="modal-head"><h3>${edit?'Edito shitjen':'Shitje e re'}</h3><button class="x" onclick="closeModal()">✕</button></div>
 <form id="saleForm" class="modal-body">${clientOperatorPickers(sale)}
  <div class="grid-2"><div class="field"><label>Hoteli / Paketa</label><input class="input" id="hotel" value="${esc(sale?sale.hotel:'')}" placeholder="p.sh. Mitsis Galini"></div><div class="field"><label>Destinacioni</label><input class="input" id="dest" value="${esc(sale?sale.destination:'')}" placeholder="p.sh. Greqi"></div></div>
  <div class="grid-3"><div class="field"><label>Data e rezervimit</label><input class="input" type="date" id="bDate" value="${sale?sale.bookingDate||'':today()}"></div><div class="field"><label>Data e udhëtimit</label><input class="input" type="date" id="tDate" value="${sale?sale.travelDate||'':''}"></div><div class="field"><label>Data e kthimit</label><input class="input" type="date" id="rDate" value="${sale?sale.returnDate||'':''}"></div></div>
  <div class="grid-2"><div class="field"><label>Kostoja e operatorit (€)</label><input class="input" type="number" min="0" step="0.01" id="cost" value="${sale?sale.operatorCost:''}"></div><div class="field"><label>Çmimi për klientin (€)</label><input class="input" type="number" min="0" step="0.01" id="sell" value="${sale?sale.sellingPrice:''}"></div></div>
  ${edit?'':`<div class="grid-2"><div class="field"><label>Parapagim i klientit (opsional)</label><input class="input" type="number" min="0" step="0.01" id="cpay" placeholder="0"></div><div class="field"><label>Paguar operatorit (opsional)</label><input class="input" type="number" min="0" step="0.01" id="opay" placeholder="0"></div></div>`}
  <div class="profit-hint" id="pHint"></div>
  <div class="modal-foot"><button type="button" class="btn btn-secondary" onclick="closeModal()">Anulo</button><button class="btn btn-primary" type="submit">${edit?'Ruaj ndryshimet':'Krijo shitjen'}</button></div>
 </form>`,true);
 bindPickers();
 const upd=()=>{const s=parseFloat($('#sell').value)||0,co=parseFloat($('#cost').value)||0;const cp=parseFloat(($('#cpay')||{}).value)||0;$('#pHint').innerHTML=`Fitimi i pritur: <strong class="pos">${money(s-co)}</strong> • Borxhi fillestar i klientit: <strong>${money(s-cp)}</strong>`;};
 ['#sell','#cost','#cpay'].forEach(id=>{const el=$(id);if(el)el.oninput=upd;});upd();
 $('#saleForm').onsubmit=async e=>{e.preventDefault();const btn=e.target.querySelector('button[type=submit]');btn.disabled=true;try{const body=gatherPickers();Object.assign(body,{hotel:$('#hotel').value.trim(),destination:$('#dest').value.trim(),bookingDate:$('#bDate').value,travelDate:$('#tDate').value,returnDate:$('#rDate').value,operatorCost:$('#cost').value,sellingPrice:$('#sell').value});if(!edit){body.clientPayment=$('#cpay').value;body.operatorPayment=$('#opay').value;}await api(edit?'/sales/'+sale.id:'/sales',{method:edit?'PUT':'POST',body:JSON.stringify(body)});closeModal();toast(edit?'Shitja u përditësua.':'Shitja u krijua.');await load();}catch(x){btn.disabled=false;toast(x.message);}};
}
function paymentModal(s){openModal(`<div class="modal-head"><h3>Pagesë — ${esc(s.bookingId)}</h3><button class="x" onclick="closeModal()">✕</button></div>
 <form id="payForm" class="modal-body"><div class="pay-summary"><div><span>Çmimi</span><strong>${money(s.sellingPrice)}</strong></div><div><span>Paguar</span><strong>${money(s.clientPaid)}</strong></div><div><span>Borxh klienti</span><strong class="neg">${money(s.clientDebt)}</strong></div><div><span>Borxh operatori</span><strong class="neg">${money(s.operatorDebt)}</strong></div></div>
  <div class="field"><label>Lloji i pagesës</label><select class="input" id="pKind"><option value="client">Arkëtim nga klienti</option><option value="operator">Pagesë te operatori</option></select></div>
  <div class="grid-2"><div class="field"><label>Shuma (€)</label><input class="input" type="number" min="0" step="0.01" id="pAmt" required></div><div class="field"><label>Data</label><input class="input" type="date" id="pDate" value="${today()}"></div></div>
  <div class="field" id="pMethodF"><label>Mënyra</label><select class="input" id="pMethod"><option>Kesh</option><option>Bankë</option><option>Kartë</option></select></div>
  <div class="modal-foot"><button type="button" class="btn btn-secondary" onclick="closeModal()">Anulo</button><button class="btn btn-primary" type="submit">Regjistro pagesën</button></div></form>`);
 $('#pKind').onchange=e=>$('#pMethodF').classList.toggle('hidden',e.target.value==='operator');
 $('#payForm').onsubmit=async e=>{e.preventDefault();try{await api('/sales/'+s.id+'/payment',{method:'POST',body:JSON.stringify({kind:$('#pKind').value,amount:$('#pAmt').value,date:$('#pDate').value,method:$('#pMethod').value})});closeModal();toast('Pagesa u regjistrua.');await load();}catch(x){toast(x.message);}};
}
function exportCsv(rows){const head=['Booking','Klienti','Destinacioni','Operatori','Rezervimi','Udhetimi','Kthimi','Cmimi','Paguar','Borxh','Fitim','Statusi'];const lines=[head.join(',')].concat(rows.map(s=>[s.bookingId,s.clientName,s.destination,s.operatorName,s.bookingDate,s.travelDate,s.returnDate,s.sellingPrice,s.clientPaid,s.clientDebt,s.profit,s.paymentStatus].map(v=>`"${String(v==null?'':v).replace(/"/g,'""')}"`).join(',')));const blob=new Blob(['\ufeff'+lines.join('\n')],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='shitjet.csv';a.click();toast('CSV u eksportua.');}

/* ---------------- CLIENTS ---------------- */
function clients(c){const d=state.data;const f=(state.filter||'').toLowerCase();const debtBy={};d.sales.forEach(s=>{debtBy[s.clientId]=debtBy[s.clientId]||{spent:0,debt:0,n:0};debtBy[s.clientId].spent+=s.sellingPrice;debtBy[s.clientId].debt+=s.clientDebt;debtBy[s.clientId].n++;});
 let rows=d.clients.filter(x=>!f||[x.name,x.email,x.phone].join(' ').toLowerCase().includes(f));
 c.innerHTML=heading('Klientët','Regjistri i klientëve dhe bilancet e tyre.',`<button class="btn btn-primary" id="newC">+ Klient i ri</button>`)
 +`<div class="toolbar"><input class="input search" id="q" placeholder="Kërko klient…" value="${esc(state.filter||'')}"><span class="count">${rows.length}</span></div>
 <div class="card"><div class="table-wrap"><table><thead><tr><th>Emri</th><th>Kontakti</th><th class="num">Rezervime</th><th class="num">Shpenzuar</th><th class="num">Borxh</th><th class="ta-r">Veprime</th></tr></thead><tbody>
 ${rows.map(x=>{const b=debtBy[x.id]||{spent:0,debt:0,n:0};return `<tr><td><strong>${esc(x.name)}</strong>${x.address?`<div class="sub">${esc(x.address)}</div>`:''}</td><td>${esc(x.phone||'')}<div class="sub">${esc(x.email||'')}</div></td><td class="num">${b.n}</td><td class="num">${money(b.spent)}</td><td class="num ${b.debt>0?'neg':''}">${money(b.debt)}</td><td class="ta-r"><div class="rowbtns"><button class="mini" data-inv="${x.id}" title="Faturë">🧾</button><button class="mini" data-edit="${x.id}" title="Edito">✎</button><button class="mini danger" data-del="${x.id}" title="Fshi">✕</button></div></td></tr>`;}).join('')||`<tr><td colspan="6" class="empty">Nuk ka klientë.</td></tr>`}
 </tbody></table></div></div>`;
 $('#newC').onclick=()=>clientModal();
 $('#q').oninput=e=>{state.filter=e.target.value;const cur=e.target.selectionStart;clients(c);$('#q').focus();$('#q').setSelectionRange(cur,cur);};
 $$('[data-edit]').forEach(b=>b.onclick=()=>clientModal(d.clients.find(x=>x.id===b.dataset.edit)));
 $$('[data-del]').forEach(b=>b.onclick=()=>confirmDel('Këtë klient',async()=>{try{await api('/clients/'+b.dataset.del,{method:'DELETE'});toast('Klienti u fshi.');await load();}catch(x){toast(x.message);}}));
 $$('[data-inv]').forEach(b=>b.onclick=()=>invoiceModal(null,null,b.dataset.inv));
}
function clientModal(cl){const edit=!!cl;openModal(`<div class="modal-head"><h3>${edit?'Edito klientin':'Klient i ri'}</h3><button class="x" onclick="closeModal()">✕</button></div><form id="cForm" class="modal-body"><div class="field"><label>Emri *</label><input class="input" id="cn" value="${esc(cl?cl.name:'')}" required></div><div class="grid-2"><div class="field"><label>Telefoni</label><input class="input" id="cp" value="${esc(cl?cl.phone:'')}"></div><div class="field"><label>Email</label><input class="input" id="ce" value="${esc(cl?cl.email:'')}"></div></div><div class="field"><label>Adresa</label><input class="input" id="ca" value="${esc(cl?cl.address:'')}"></div><div class="field"><label>Shënime</label><textarea class="input" id="cnotes">${esc(cl?cl.notes:'')}</textarea></div><div class="modal-foot"><button type="button" class="btn btn-secondary" onclick="closeModal()">Anulo</button><button class="btn btn-primary">Ruaj</button></div></form>`);
 $('#cForm').onsubmit=async e=>{e.preventDefault();try{const body={name:$('#cn').value.trim(),phone:$('#cp').value.trim(),email:$('#ce').value.trim(),address:$('#ca').value.trim(),notes:$('#cnotes').value.trim()};await api(edit?'/clients/'+cl.id:'/clients',{method:edit?'PUT':'POST',body:JSON.stringify(body)});closeModal();toast('U ruajt.');await load();}catch(x){toast(x.message);}};}

/* ---------------- PAYMENTS ---------------- */
function payments(c){const d=state.data;const open=d.sales.filter(s=>s.clientDebt>0.001);const opOpen=d.sales.filter(s=>s.operatorDebt>0.001);
 c.innerHTML=heading('Pagesat','Arkëtime nga klientët dhe pagesa te operatorët.','')
 +`<section class="kpis three">${kpi('Për t’u arkëtuar',money(d.kpis.clientDebt),open.length+' shitje','tone-amber')}${kpi('Arkëtuar gjithsej',money(d.kpis.received),'nga klientët','tone-green')}${kpi('Detyrime operatorësh',money(d.kpis.operatorDebt),opOpen.length+' shitje','tone-red')}</section>
 <article class="card"><div class="card-head"><h3>Borxhe të klientëve</h3></div><div class="table-wrap"><table><thead><tr><th>Booking</th><th>Klienti</th><th class="num">Çmimi</th><th class="num">Paguar</th><th class="num">Borxh</th><th>Statusi</th><th class="ta-r">Veprime</th></tr></thead><tbody>${open.map(s=>`<tr><td class="mono">${esc(s.bookingId)}</td><td>${esc(s.clientName)}</td><td class="num">${money(s.sellingPrice)}</td><td class="num">${money(s.clientPaid)}</td><td class="num neg">${money(s.clientDebt)}</td><td>${statusBadge(s.paymentStatus)}</td><td class="ta-r"><button class="btn btn-secondary sm" data-pay="${s.id}">+ Pagesë</button></td></tr>`).join('')||`<tr><td colspan="7" class="empty">Asnjë borxh i hapur. 🎉</td></tr>`}</tbody></table></div></article>
 <article class="card"><div class="card-head"><h3>Detyrime ndaj operatorëve</h3></div><div class="table-wrap"><table><thead><tr><th>Booking</th><th>Operatori</th><th class="num">Kostoja</th><th class="num">Paguar</th><th class="num">Borxh</th><th class="ta-r">Veprime</th></tr></thead><tbody>${opOpen.map(s=>`<tr><td class="mono">${esc(s.bookingId)}</td><td>${esc(s.operatorName)}</td><td class="num">${money(s.operatorCost)}</td><td class="num">${money(s.operatorPaid)}</td><td class="num neg">${money(s.operatorDebt)}</td><td class="ta-r"><button class="btn btn-secondary sm" data-pay="${s.id}">+ Pagesë</button></td></tr>`).join('')||`<tr><td colspan="6" class="empty">Asnjë detyrim i hapur.</td></tr>`}</tbody></table></div></article>`;
 $$('[data-pay]').forEach(b=>b.onclick=()=>paymentModal(d.sales.find(s=>s.id===b.dataset.pay)));
}

/* ---------------- INVOICES ---------------- */
function invoices(c){const d=state.data;const f=(state.filter||'').toLowerCase();let rows=d.invoices.filter(i=>!f||[i.invoiceNo,i.clientName].join(' ').toLowerCase().includes(f));
 const tot=d.invoices.reduce((a,i)=>a+i.total,0);const unpaid=d.invoices.filter(i=>i.status!=='E paguar').reduce((a,i)=>a+i.total,0);
 c.innerHTML=heading('Fatura','Gjenero fatura profesionale me TVSH, shkarko në PDF, edito ose fshi.',`<button class="btn btn-primary" id="newInv">+ Faturë e re</button>`)
 +`<section class="kpis three">${kpi('Fatura gjithsej',d.invoices.length,'të lëshuara')}${kpi('Vlera totale',money2(tot),'me TVSH')}${kpi('Të papaguara',money2(unpaid),'për arkëtim','tone-amber')}</section>
 <div class="toolbar"><input class="input search" id="q" placeholder="Kërko faturë…" value="${esc(state.filter||'')}"><span class="count">${rows.length}</span></div>
 <div class="card"><div class="table-wrap"><table><thead><tr><th>Nr. Fakturë</th><th>Klienti</th><th>Data</th><th>Afati</th><th class="num">Nën-total</th><th class="num">TVSH</th><th class="num">Totali</th><th>Statusi</th><th class="ta-r">Veprime</th></tr></thead><tbody>
 ${rows.map(i=>`<tr><td class="mono">${esc(i.invoiceNo)}</td><td>${esc(i.clientName)}</td><td>${fmtDate(i.date)}</td><td>${fmtDate(i.dueDate)}</td><td class="num">${money2(i.subtotal)}</td><td class="num">${money2(i.vatAmount)} <span class="sub">(${i.vatRate}%)</span></td><td class="num"><strong>${money2(i.total)}</strong></td><td>${i.status==='E paguar'?'<span class="badge ok">E paguar</span>':'<span class="badge warn">E papaguar</span>'}</td><td class="ta-r"><div class="rowbtns"><button class="mini" data-view="${i.id}" title="Shiko/PDF">👁</button><button class="mini" data-pdf="${i.id}" title="Shkarko PDF">⤓</button><button class="mini" data-edit="${i.id}" title="Edito">✎</button><button class="mini danger" data-del="${i.id}" title="Fshi">✕</button></div></td></tr>`).join('')||`<tr><td colspan="9" class="empty">Ende nuk ka fatura. Krijoni të parën!</td></tr>`}
 </tbody></table></div></div>`;
 $('#newInv').onclick=()=>invoiceModal();
 $('#q').oninput=e=>{state.filter=e.target.value;const cur=e.target.selectionStart;invoices(c);$('#q').focus();$('#q').setSelectionRange(cur,cur);};
 $$('[data-view]').forEach(b=>b.onclick=()=>viewInvoice(d.invoices.find(i=>i.id===b.dataset.view)));
 $$('[data-pdf]').forEach(b=>b.onclick=()=>printHTML(invoiceHTML(d.invoices.find(i=>i.id===b.dataset.pdf))));
 $$('[data-edit]').forEach(b=>b.onclick=()=>invoiceModal(d.invoices.find(i=>i.id===b.dataset.edit)));
 $$('[data-del]').forEach(b=>b.onclick=()=>confirmDel('Këtë faturë',async()=>{await api('/invoices/'+b.dataset.del,{method:'DELETE'});toast('Fatura u fshi.');await load();}));
}
function invoiceModal(inv,sale,clientId){const edit=!!inv;const d=state.data;
 let items=inv?inv.items.slice():[];if(!items.length){if(sale)items=[{desc:`Paketë turistike ${sale.destination} — ${sale.hotel||''}`.trim(),qty:1,price:sale.sellingPrice}];else items=[{desc:'',qty:1,price:0}];}
 const selClient=inv?inv.clientId:(sale?sale.clientId:(clientId||(d.clients[0]&&d.clients[0].id)));
 const vat=inv?inv.vatRate:18;
 openModal(`<div class="modal-head"><h3>${edit?'Edito faturën '+esc(inv.invoiceNo):'Faturë e re'}</h3><button class="x" onclick="closeModal()">✕</button></div>
 <form id="invForm" class="modal-body">
  <div class="field"><label>Klienti</label><select class="input" id="invClient">${d.clients.map(c=>`<option value="${c.id}" ${c.id===selClient?'selected':''}>${esc(c.name)}</option>`).join('')}<option value="__new__">➕ Shto klient të ri…</option></select><div id="invNewC" class="subform hidden"><div class="grid-2"><input class="input" id="invNcName" placeholder="Emri *"><input class="input" id="invNcPhone" placeholder="Telefoni"></div><input class="input" id="invNcEmail" placeholder="Email"></div></div>
  <div class="grid-3"><div class="field"><label>Data</label><input class="input" type="date" id="invDate" value="${inv?inv.date:today()}"></div><div class="field"><label>Afati i pagesës</label><input class="input" type="date" id="invDue" value="${inv?inv.dueDate||'':''}"></div><div class="field"><label>Statusi</label><select class="input" id="invStatus"><option ${inv&&inv.status==='E papaguar'?'selected':''}>E papaguar</option><option ${inv&&inv.status==='E paguar'?'selected':''}>E paguar</option></select></div></div>
  <label class="blocklab">Artikujt</label><div id="itemRows"></div><button type="button" class="btn btn-secondary sm" id="addItem">+ Shto artikull</button>
  <div class="grid-2" style="margin-top:14px"><div class="field"><label>TVSH (%)</label><input class="input" type="number" min="0" max="100" step="0.1" id="invVat" value="${vat}"></div><div class="totals-box" id="invTotals"></div></div>
  <div class="field"><label>Shënime</label><textarea class="input" id="invNotes">${esc(inv?inv.notes:'Faleminderit që zgjodhët shërbimet tona.')}</textarea></div>
  <div class="modal-foot"><button type="button" class="btn btn-secondary" onclick="closeModal()">Anulo</button><button class="btn btn-primary" type="submit">${edit?'Ruaj faturën':'Krijo faturën'}</button></div>
 </form>`,true);
 const ic=$('#invClient');ic.onchange=()=>$('#invNewC').classList.toggle('hidden',ic.value!=='__new__');
 function drawItems(){$('#itemRows').innerHTML=items.map((it,idx)=>`<div class="item-row"><input class="input" data-i="${idx}" data-k="desc" placeholder="Përshkrimi" value="${esc(it.desc)}"><input class="input qty" type="number" min="0" step="1" data-i="${idx}" data-k="qty" value="${it.qty}"><input class="input price" type="number" min="0" step="0.01" data-i="${idx}" data-k="price" value="${it.price}"><span class="line-tot">${money2((Number(it.qty)||0)*(Number(it.price)||0))}</span><button type="button" class="mini danger" data-rm="${idx}">✕</button></div>`).join('');
  $$('#itemRows [data-k]').forEach(el=>{el.oninput=()=>{items[el.dataset.i][el.dataset.k]=el.dataset.k==='desc'?el.value:parseFloat(el.value)||0;const st=el.selectionStart;drawTotals();if(el.dataset.k!=='desc'){}el.dataset.k==='desc';};el.onchange=()=>{drawItems();};});
  $$('#itemRows [data-rm]').forEach(b=>b.onclick=()=>{items.splice(+b.dataset.rm,1);if(!items.length)items.push({desc:'',qty:1,price:0});drawItems();drawTotals();});}
 function drawTotals(){const sub=items.reduce((a,it)=>a+(Number(it.qty)||0)*(Number(it.price)||0),0);const vr=parseFloat($('#invVat').value)||0;const va=sub*vr/100;$('#invTotals').innerHTML=`<div><span>Nën-total</span><strong>${money2(sub)}</strong></div><div><span>TVSH (${vr}%)</span><strong>${money2(va)}</strong></div><div class="grand"><span>TOTALI</span><strong>${money2(sub+va)}</strong></div>`;}
 $('#addItem').onclick=()=>{items.push({desc:'',qty:1,price:0});drawItems();drawTotals();};
 $('#invVat').oninput=drawTotals;drawItems();drawTotals();
 $('#invForm').onsubmit=async e=>{e.preventDefault();try{const body={date:$('#invDate').value,dueDate:$('#invDue').value,status:$('#invStatus').value,vatRate:$('#invVat').value,notes:$('#invNotes').value,items:items.filter(it=>it.desc||it.price)};if(ic.value==='__new__'){const name=$('#invNcName').value.trim();if(!name)throw new Error('Shkruani emrin e klientit.');body.newClient={name,phone:$('#invNcPhone').value.trim(),email:$('#invNcEmail').value.trim()};}else body.clientId=ic.value;if(sale)body.saleId=sale.id;await api(edit?'/invoices/'+inv.id:'/invoices',{method:edit?'PUT':'POST',body:JSON.stringify(body)});closeModal();toast(edit?'Fatura u përditësua.':'Fatura u krijua.');await load();}catch(x){toast(x.message);}};
}
function viewInvoice(i){openModal(`<div class="modal-head"><h3>Fatura ${esc(i.invoiceNo)}</h3><button class="x" onclick="closeModal()">✕</button></div><div class="modal-body"><div class="invoice-preview">${invoiceInner(i)}</div><div class="modal-foot"><button class="btn btn-secondary" onclick="closeModal()">Mbyll</button><button class="btn btn-primary" id="dlPdf">⤓ Shkarko PDF</button></div></div>`,true);$('#dlPdf').onclick=()=>printHTML(invoiceHTML(i));}
function invoiceInner(i){const co=state.data.company||{};const cl=i.client||{name:i.clientName};return `<div class="inv-sheet"><div class="inv-top"><div><div class="inv-logo">${esc(co.displayName||co.name||'DataManagment')}</div><div class="inv-firm">${esc(co.name||'')}<br>${esc(co.address||'')}<br>${co.phone?esc(co.phone)+' • ':''}${esc(co.email||'')}${co.nui?'<br>NUI: '+esc(co.nui):''}</div></div><div class="inv-meta"><h2>FATURË</h2><div><span>Nr.</span> <strong>${esc(i.invoiceNo)}</strong></div><div><span>Data</span> ${fmtDate(i.date)}</div><div><span>Afati</span> ${fmtDate(i.dueDate)}</div></div></div>
 <div class="inv-bill"><div><span class="lbl">Faturuar për</span><strong>${esc(cl.name||'')}</strong><div>${esc(cl.address||'')}</div><div>${esc(cl.phone||'')} ${cl.email?'• '+esc(cl.email):''}</div></div><div class="inv-status ${i.status==='E paguar'?'paid':'due'}">${esc(i.status)}</div></div>
 <table class="inv-table"><thead><tr><th>Përshkrimi</th><th class="num">Sasia</th><th class="num">Çmimi</th><th class="num">Vlera</th></tr></thead><tbody>${i.items.map(it=>`<tr><td>${esc(it.desc)}</td><td class="num">${it.qty}</td><td class="num">${money2(it.price)}</td><td class="num">${money2((Number(it.qty)||0)*(Number(it.price)||0))}</td></tr>`).join('')}</tbody></table>
 <div class="inv-tot"><div><span>Nën-total</span><strong>${money2(i.subtotal)}</strong></div><div><span>TVSH (${i.vatRate}%)</span><strong>${money2(i.vatAmount)}</strong></div><div class="grand"><span>TOTALI PËR PAGESË</span><strong>${money2(i.total)}</strong></div></div>
 ${i.notes?`<div class="inv-notes"><strong>Shënime:</strong> ${esc(i.notes)}</div>`:''}
 <div class="inv-foot">Faturë e gjeneruar nga DataManagment • ${esc(co.displayName||'')} • datapos.pro</div></div>`;}
function invoiceHTML(i){return `<!doctype html><html lang="sq"><head><meta charset="utf-8"><title>${esc(i.invoiceNo)}</title><style>${invoiceCss()}</style></head><body>${invoiceInner(i)}</body></html>`;}
function invoiceCss(){return `*{box-sizing:border-box;font-family:Arial,Helvetica,sans-serif}body{margin:0;padding:24px;color:#0f1b33;background:#fff}.inv-sheet{max-width:800px;margin:0 auto}.inv-top{display:flex;justify-content:space-between;border-bottom:3px solid #2563eb;padding-bottom:18px}.inv-logo{font-size:26px;font-weight:800;color:#2563eb}.inv-firm{font-size:12px;color:#55617a;margin-top:6px;line-height:1.5}.inv-meta{text-align:right}.inv-meta h2{margin:0 0 8px;letter-spacing:3px;color:#0f1b33}.inv-meta div{font-size:13px;margin:2px 0}.inv-meta span{color:#8a94a8}.inv-bill{display:flex;justify-content:space-between;align-items:flex-start;margin:22px 0}.inv-bill .lbl{display:block;font-size:11px;text-transform:uppercase;letter-spacing:1px;color:#8a94a8;margin-bottom:4px}.inv-bill strong{font-size:16px}.inv-bill div{font-size:13px;color:#55617a}.inv-status{padding:6px 16px;border-radius:20px;font-weight:700;font-size:13px}.inv-status.paid{background:#e6f6ee;color:#178a57}.inv-status.due{background:#fff2e0;color:#b76a08}.inv-table{width:100%;border-collapse:collapse;margin-top:10px}.inv-table th{background:#f3f6fc;text-align:left;padding:10px 12px;font-size:12px;text-transform:uppercase;letter-spacing:.5px;color:#55617a;border-bottom:2px solid #e3e9f4}.inv-table td{padding:11px 12px;border-bottom:1px solid #eef2f9;font-size:14px}.num{text-align:right}.inv-tot{margin-left:auto;width:300px;margin-top:16px}.inv-tot div{display:flex;justify-content:space-between;padding:6px 0;font-size:14px}.inv-tot .grand{border-top:2px solid #0f1b33;margin-top:6px;padding-top:10px;font-size:17px;font-weight:800;color:#2563eb}.inv-notes{margin-top:26px;padding:14px 16px;background:#f7f9fd;border-radius:8px;font-size:13px;color:#55617a}.inv-foot{margin-top:30px;text-align:center;font-size:11px;color:#9aa4b8;border-top:1px solid #eef2f9;padding-top:12px}@media print{body{padding:0}}`;}
function printHTML(html){const f=document.createElement('iframe');f.style.cssText='position:fixed;right:0;bottom:0;width:0;height:0;border:0;';document.body.appendChild(f);const doc=f.contentWindow.document;doc.open();doc.write(html);doc.close();const go=()=>{try{f.contentWindow.focus();f.contentWindow.print();}catch(e){}setTimeout(()=>{try{document.body.removeChild(f);}catch(e){}},1500);};f.onload=go;setTimeout(go,400);toast('Zgjidhni “Save as PDF” për ta shkarkuar.');}

/* ---------------- OPERATORS ---------------- */
function operators(c){const d=state.data;c.innerHTML=heading('Operatorët','Partnerët tuaj dhe detyrimet e hapura.',`<button class="btn btn-primary" id="newOp">+ Operator i ri</button>`)
 +`<div class="card"><div class="table-wrap"><table><thead><tr><th>Operatori</th><th>Kontakti</th><th class="num">Rezervime</th><th class="num">Kostoja</th><th class="num">Paguar</th><th class="num">Borxh</th><th class="ta-r">Veprime</th></tr></thead><tbody>${d.operators.map(o=>`<tr><td><strong>${esc(o.name)}</strong></td><td>${esc(o.phone||'')}<div class="sub">${esc(o.email||'')}</div></td><td class="num">${o.bookings}</td><td class="num">${money(o.totalCost)}</td><td class="num">${money(o.paid)}</td><td class="num ${o.debt>0?'neg':''}">${money(o.debt)}</td><td class="ta-r"><div class="rowbtns">${o.debt>0?`<button class="btn btn-secondary sm" data-pay="${o.id}">+ Pagesë</button>`:''}<button class="mini" data-edit="${o.id}" title="Edito">✎</button><button class="mini danger" data-del="${o.id}" title="Fshi">✕</button></div></td></tr>`).join('')||`<tr><td colspan="7" class="empty">Nuk ka operatorë.</td></tr>`}</tbody></table></div></div>`;
 $('#newOp').onclick=()=>operatorModal();
 $$('[data-edit]').forEach(b=>b.onclick=()=>operatorModal(d.operators.find(o=>o.id===b.dataset.edit)));
 $$('[data-del]').forEach(b=>b.onclick=()=>confirmDel('Këtë operator',async()=>{try{await api('/operators/'+b.dataset.del,{method:'DELETE'});toast('Operatori u fshi.');await load();}catch(x){toast(x.message);}}));
 $$('[data-pay]').forEach(b=>b.onclick=()=>{const o=d.operators.find(x=>x.id===b.dataset.pay);openModal(`<div class="modal-head"><h3>Pagesë operatorit — ${esc(o.name)}</h3><button class="x" onclick="closeModal()">✕</button></div><form id="opPay" class="modal-body"><p class="muted">Borxhi total: <strong class="neg">${money(o.debt)}</strong>. Pagesa shpërndahet automatikisht te rezervimet e hapura.</p><div class="grid-2"><div class="field"><label>Shuma (€)</label><input class="input" type="number" min="0" step="0.01" id="opAmt" value="${o.debt}" required></div><div class="field"><label>Data</label><input class="input" type="date" id="opDate" value="${today()}"></div></div><div class="modal-foot"><button type="button" class="btn btn-secondary" onclick="closeModal()">Anulo</button><button class="btn btn-primary">Regjistro</button></div></form>`);$('#opPay').onsubmit=async e=>{e.preventDefault();try{await api('/operators/'+o.id+'/payment',{method:'POST',body:JSON.stringify({amount:$('#opAmt').value,date:$('#opDate').value})});closeModal();toast('Pagesa u regjistrua.');await load();}catch(x){toast(x.message);}};});
}
function operatorModal(o){const edit=!!o;openModal(`<div class="modal-head"><h3>${edit?'Edito operatorin':'Operator i ri'}</h3><button class="x" onclick="closeModal()">✕</button></div><form id="oForm" class="modal-body"><div class="field"><label>Emri *</label><input class="input" id="on" value="${esc(o?o.name:'')}" required></div><div class="grid-2"><div class="field"><label>Telefoni</label><input class="input" id="op" value="${esc(o?o.phone:'')}"></div><div class="field"><label>Email</label><input class="input" id="oe" value="${esc(o?o.email:'')}"></div></div><div class="modal-foot"><button type="button" class="btn btn-secondary" onclick="closeModal()">Anulo</button><button class="btn btn-primary">Ruaj</button></div></form>`);$('#oForm').onsubmit=async e=>{e.preventDefault();try{await api(edit?'/operators/'+o.id:'/operators',{method:edit?'PUT':'POST',body:JSON.stringify({name:$('#on').value.trim(),phone:$('#op').value.trim(),email:$('#oe').value.trim()})});closeModal();toast('U ruajt.');await load();}catch(x){toast(x.message);}};}

/* ---------------- EXPENSES ---------------- */
function expenses(c){const d=state.data;c.innerHTML=heading('Shpenzimet','Shpenzimet operative të biznesit.',`<button class="btn btn-primary" id="newE">+ Shpenzim</button>`)
 +`<section class="kpis three">${kpi('Shpenzime totale',money(d.kpis.expenses),d.expenses.length+' zëra','tone-red')}${kpi('Fitimi bruto',money(d.kpis.profit),'')}${kpi('Fitimi neto',money(d.kpis.netProfit),'pas shpenzimeve','tone-green')}</section>
 <div class="card"><div class="table-wrap"><table><thead><tr><th>Data</th><th>Kategoria</th><th>Shënim</th><th class="num">Shuma</th><th class="ta-r">Veprime</th></tr></thead><tbody>${d.expenses.map(e=>`<tr><td>${fmtDate(e.date)}</td><td>${esc(e.category)}</td><td>${esc(e.note||'')}</td><td class="num neg">${money(e.amount)}</td><td class="ta-r"><button class="mini danger" data-del="${e.id}">✕</button></td></tr>`).join('')||`<tr><td colspan="5" class="empty">Nuk ka shpenzime.</td></tr>`}</tbody></table></div></div>`;
 $('#newE').onclick=()=>{openModal(`<div class="modal-head"><h3>Shpenzim i ri</h3><button class="x" onclick="closeModal()">✕</button></div><form id="eForm" class="modal-body"><div class="grid-2"><div class="field"><label>Data</label><input class="input" type="date" id="ed" value="${today()}"></div><div class="field"><label>Kategoria</label><select class="input" id="ec"><option>Marketing</option><option>Zyra</option><option>Paga</option><option>Sistemi</option><option>Transport</option><option>Tjetër</option></select></div></div><div class="field"><label>Shuma (€)</label><input class="input" type="number" min="0" step="0.01" id="ea" required></div><div class="field"><label>Shënim</label><input class="input" id="en"></div><div class="modal-foot"><button type="button" class="btn btn-secondary" onclick="closeModal()">Anulo</button><button class="btn btn-primary">Ruaj</button></div></form>`);$('#eForm').onsubmit=async e=>{e.preventDefault();try{await api('/expenses',{method:'POST',body:JSON.stringify({date:$('#ed').value,category:$('#ec').value,amount:$('#ea').value,note:$('#en').value.trim()})});closeModal();toast('Shpenzimi u shtua.');await load();}catch(x){toast(x.message);}};};
 $$('[data-del]').forEach(b=>b.onclick=()=>confirmDel('Këtë shpenzim',async()=>{await api('/expenses/'+b.dataset.del,{method:'DELETE'});toast('U fshi.');await load();}));
}

/* ---------------- REPORTS ---------------- */
function reports(c){const d=state.data;const k=d.kpis;const co=d.company||{};
 const byMonth={};d.sales.forEach(s=>{const m=(s.travelDate||s.bookingDate||'').slice(0,7);if(!m)return;byMonth[m]=byMonth[m]||{sales:0,profit:0,paid:0,n:0};byMonth[m].sales+=s.sellingPrice;byMonth[m].profit+=s.profit;byMonth[m].paid+=s.clientPaid;byMonth[m].n++;});
 const months=Object.keys(byMonth).sort();
 const dest={};d.sales.forEach(s=>{dest[s.destination]=dest[s.destination]||{sales:0,profit:0,n:0};dest[s.destination].sales+=s.sellingPrice;dest[s.destination].profit+=s.profit;dest[s.destination].n++;});
 const topDest=Object.entries(dest).sort((a,b)=>b[1].sales-a[1].sales);
 const period=months.length?`${months[0]} — ${months[months.length-1]}`:'—';
 const reportBody=reportInner(co,k,months,byMonth,topDest,d.operators,period);
 c.innerHTML=heading('Raportet','Raport financiar profesional — gati për printim ose PDF.',`<button class="btn btn-secondary" id="prn">⤓ Shkarko / Printo PDF</button>`)
 +`<div class="report-canvas">${reportBody}</div>`;
 $('#prn').onclick=()=>printHTML(`<!doctype html><html lang="sq"><head><meta charset="utf-8"><title>Raport ${esc(co.displayName||'')}</title><style>${reportCss()}</style></head><body>${reportBody}</body></html>`);
}
function reportInner(co,k,months,byMonth,topDest,operators,period){const mn=['Jan','Shk','Mar','Pri','Maj','Qer','Kor','Gsh','Sht','Tet','Nën','Dhj'];const ml=m=>{const p=m.split('-');return mn[(+p[1])-1]+' '+p[0];};const maxS=Math.max(1,...months.map(m=>byMonth[m].sales));
 return `<div class="report-sheet"><header class="rep-head"><div><div class="rep-logo">${esc(co.displayName||co.name||'DataManagment')}</div><div class="rep-sub">${esc(co.name||'')} • ${esc(co.address||'')}</div></div><div class="rep-title"><h1>Raport Financiar</h1><div>Periudha: <strong>${esc(period)}</strong></div><div class="muted2">Lëshuar më ${fmtDate(today())}</div></div></header>
 <section class="rep-kpis"><div><span>Shitje totale</span><strong>${money(k.totalSales)}</strong></div><div><span>Fitimi bruto</span><strong>${money(k.profit)}</strong></div><div><span>Arkëtuar</span><strong>${money(k.received)}</strong></div><div><span>Borxhe klientësh</span><strong>${money(k.clientDebt)}</strong></div><div><span>Shpenzime</span><strong>${money(k.expenses)}</strong></div><div class="hl"><span>Fitimi neto</span><strong>${money(k.netProfit)}</strong></div></section>
 <h2 class="rep-h2">Performanca mujore</h2><table class="rep-table"><thead><tr><th>Muaji</th><th class="num">Rezervime</th><th class="num">Shitje</th><th class="num">Arkëtuar</th><th class="num">Fitim</th><th>Trendi</th></tr></thead><tbody>${months.map(m=>`<tr><td>${ml(m)}</td><td class="num">${byMonth[m].n}</td><td class="num">${money(byMonth[m].sales)}</td><td class="num">${money(byMonth[m].paid)}</td><td class="num">${money(byMonth[m].profit)}</td><td><div class="tbar"><i style="width:${byMonth[m].sales/maxS*100}%"></i></div></td></tr>`).join('')}</tbody><tfoot><tr><td>Gjithsej</td><td class="num">${months.reduce((a,m)=>a+byMonth[m].n,0)}</td><td class="num">${money(k.totalSales)}</td><td class="num">${money(k.received)}</td><td class="num">${money(k.profit)}</td><td></td></tr></tfoot></table>
 <h2 class="rep-h2">Destinacionet kryesore</h2><table class="rep-table"><thead><tr><th>Destinacioni</th><th class="num">Rezervime</th><th class="num">Shitje</th><th class="num">Fitim</th><th class="num">Marzha</th></tr></thead><tbody>${topDest.map(([n,v])=>`<tr><td>${esc(n)}</td><td class="num">${v.n}</td><td class="num">${money(v.sales)}</td><td class="num">${money(v.profit)}</td><td class="num">${v.sales?Math.round(v.profit/v.sales*100):0}%</td></tr>`).join('')}</tbody></table>
 <h2 class="rep-h2">Bilanci i operatorëve</h2><table class="rep-table"><thead><tr><th>Operatori</th><th class="num">Rezervime</th><th class="num">Kostoja</th><th class="num">Paguar</th><th class="num">Borxh</th></tr></thead><tbody>${operators.map(o=>`<tr><td>${esc(o.name)}</td><td class="num">${o.bookings}</td><td class="num">${money(o.totalCost)}</td><td class="num">${money(o.paid)}</td><td class="num">${money(o.debt)}</td></tr>`).join('')}</tbody></table>
 <footer class="rep-foot">Raport i gjeneruar automatikisht nga DataManagment • datapos.pro • ${fmtDate(today())}</footer></div>`;}
function reportCss(){return `*{box-sizing:border-box;font-family:Arial,Helvetica,sans-serif}body{margin:0;padding:24px;background:#fff;color:#0f1b33}.report-sheet{max-width:900px;margin:0 auto}.rep-head{display:flex;justify-content:space-between;align-items:flex-start;border-bottom:3px solid #2563eb;padding-bottom:16px}.rep-logo{font-size:24px;font-weight:800;color:#2563eb}.rep-sub{font-size:12px;color:#55617a;margin-top:4px}.rep-title{text-align:right}.rep-title h1{margin:0;font-size:22px}.rep-title div{font-size:13px}.muted2{color:#8a94a8}.rep-kpis{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:22px 0}.rep-kpis>div{background:#f6f9fe;border:1px solid #e6ecf7;border-radius:10px;padding:12px 14px}.rep-kpis span{display:block;font-size:11px;text-transform:uppercase;letter-spacing:.5px;color:#8a94a8}.rep-kpis strong{font-size:19px}.rep-kpis .hl{background:#e9f6ef;border-color:#bfe6d0}.rep-kpis .hl strong{color:#178a57}.rep-h2{font-size:15px;margin:26px 0 8px;padding-bottom:6px;border-bottom:2px solid #eef2f9;text-transform:uppercase;letter-spacing:.5px;color:#3a475e}.rep-table{width:100%;border-collapse:collapse}.rep-table th{background:#f3f6fc;text-align:left;padding:8px 10px;font-size:11px;text-transform:uppercase;color:#55617a;border-bottom:1px solid #e3e9f4}.rep-table td{padding:8px 10px;border-bottom:1px solid #eef2f9;font-size:13px}.rep-table tfoot td{font-weight:700;border-top:2px solid #0f1b33}.num{text-align:right}.tbar{background:#eef2f9;border-radius:6px;height:8px;min-width:60px}.tbar i{display:block;height:8px;border-radius:6px;background:#2563eb}.rep-foot{margin-top:28px;text-align:center;font-size:11px;color:#9aa4b8;border-top:1px solid #eef2f9;padding-top:12px}@media print{body{padding:0}.rep-h2{page-break-after:avoid}tr{page-break-inside:avoid}}`;}

/* ---------------- WORKERS ---------------- */
function workers(c){const d=state.data;c.innerHTML=heading('Punëtorët','Menaxhoni ekipin e firmës suaj.',`<button class="btn btn-primary" id="newW">+ Përdorues i ri</button>`)
 +`<div class="card"><div class="table-wrap"><table><thead><tr><th>Emri</th><th>Përdoruesi</th><th>Roli</th><th>Statusi</th><th class="ta-r">Veprime</th></tr></thead><tbody>${d.workers.map(w=>`<tr><td><strong>${esc(w.name)}</strong></td><td class="mono">${esc(w.username)}</td><td>${roleName(w.role)}</td><td>${w.status==='Aktiv'?'<span class="badge ok">Aktiv</span>':'<span class="badge bad">Joaktiv</span>'}</td><td class="ta-r"><div class="rowbtns"><button class="mini" data-edit="${w.id}" title="Edito">✎</button>${w.id!==state.me.id?`<button class="mini danger" data-del="${w.id}" title="Fshi">✕</button>`:''}</div></td></tr>`).join('')}</tbody></table></div></div>`;
 $('#newW').onclick=()=>workerModal();
 $$('[data-edit]').forEach(b=>b.onclick=()=>workerModal(d.workers.find(w=>w.id===b.dataset.edit)));
 $$('[data-del]').forEach(b=>b.onclick=()=>confirmDel('Këtë përdorues',async()=>{try{await api('/workers/'+b.dataset.del,{method:'DELETE'});toast('U fshi.');await load();}catch(x){toast(x.message);}}));
}
function workerModal(w){const edit=!!w;openModal(`<div class="modal-head"><h3>${edit?'Edito përdoruesin':'Përdorues i ri'}</h3><button class="x" onclick="closeModal()">✕</button></div><form id="wForm" class="modal-body"><div class="field"><label>Emri *</label><input class="input" id="wn" value="${esc(w?w.name:'')}" required></div>${edit?'':`<div class="field"><label>Përdoruesi *</label><input class="input" id="wu" required></div>`}<div class="grid-2"><div class="field"><label>${edit?'Fjalëkalim i ri (opsional)':'Fjalëkalimi *'}</label><input class="input" id="wp" type="text" ${edit?'':'required'}></div><div class="field"><label>Roli</label><select class="input" id="wr"><option value="WORKER" ${w&&w.role==='WORKER'?'selected':''}>Punëtor</option><option value="COMPANY_ADMIN" ${w&&w.role==='COMPANY_ADMIN'?'selected':''}>Administrator firme</option></select></div></div>${edit?`<div class="field"><label>Statusi</label><select class="input" id="ws"><option ${w.status==='Aktiv'?'selected':''}>Aktiv</option><option ${w.status!=='Aktiv'?'selected':''}>Joaktiv</option></select></div>`:''}<div class="modal-foot"><button type="button" class="btn btn-secondary" onclick="closeModal()">Anulo</button><button class="btn btn-primary">Ruaj</button></div></form>`);
 $('#wForm').onsubmit=async e=>{e.preventDefault();try{const body={name:$('#wn').value.trim(),role:$('#wr').value};if(!edit){body.username=$('#wu').value.trim();body.password=$('#wp').value;}else{if($('#wp').value)body.password=$('#wp').value;body.status=$('#ws').value;}await api(edit?'/workers/'+w.id:'/workers',{method:edit?'PUT':'POST',body:JSON.stringify(body)});closeModal();toast('U ruajt.');await load();}catch(x){toast(x.message);}};}

/* ---------------- AUDIT ---------------- */
function auditPage(c){const arr=Array.isArray(state.data.audit)?state.data.audit:[];
 c.innerHTML=heading('Historiku','Gjurma e veprimeve në sistem.','')+`<div class="card"><div class="table-wrap"><table><thead><tr><th>Data</th><th>Përdoruesi</th><th>Veprimi</th></tr></thead><tbody>${arr.slice(-200).reverse().map(a=>`<tr><td>${new Date(a.at).toLocaleString('sq-AL')}</td><td>${esc(a.who)}</td><td>${esc(a.action)}</td></tr>`).join('')||`<tr><td colspan="3" class="empty">Ende nuk ka veprime.</td></tr>`}</tbody></table></div></div>`;}

/* ---------------- SUPER ADMIN ---------------- */
function superDash(c){const d=state.data;c.innerHTML=heading('Pasqyra e platformës','Menaxhoni firmat dhe administratorët. Të dhënat financiare të firmave janë të izoluara.','')
 +`<section class="kpis">${kpi('Firma',d.companies.length,'gjithsej')}${kpi('Aktive',d.companies.filter(x=>x.status==='Aktiv').length,'')}${kpi('Administratorë',d.users.filter(u=>u.role==='COMPANY_ADMIN').length,'')}${kpi('Përdorues',d.users.length,'')}</section>`+superTable(true);
 bindNewCo();bindCompanyRows();
}
function superTable(withBtn){const d=state.data;return `<article class="card"><div class="card-head"><h3>Firmat</h3>${withBtn?'<button class="btn btn-primary sm" id="newCo">+ Firmë e re</button>':''}</div><div class="table-wrap"><table><thead><tr><th>Firma</th><th>Subdomaini</th><th class="num">Admin</th><th class="num">Shitje</th><th>Statusi</th><th class="ta-r">Veprime</th></tr></thead><tbody>${d.companies.map(co=>`<tr><td><strong>${esc(co.name)}</strong><div class="sub">${esc(co.displayName||'')}</div></td><td class="mono">${esc(co.subdomain)}.datapos.pro</td><td class="num">${co.admins}</td><td class="num">${co.sales}</td><td>${co.status==='Aktiv'?'<span class="badge ok">Aktiv</span>':'<span class="badge bad">'+esc(co.status)+'</span>'}</td><td class="ta-r"><div class="rowbtns"><button class="mini" data-admins="${co.id}" title="Administratorët">👤</button><button class="mini" data-edit="${co.id}" title="Edito">✎</button><button class="mini danger" data-del="${co.id}" title="Fshi">✕</button></div></td></tr>`).join('')}</tbody></table></div></article>`;}
function superCompanies(c){c.innerHTML=heading('Firmat','Krijoni dhe menaxhoni firmat me subdomainet e tyre.',`<button class="btn btn-primary" id="newCo">+ Firmë e re</button>`)+superTable(false);bindNewCo();bindCompanyRows();}
function bindNewCo(){const b=$('#newCo');if(b)b.onclick=()=>companyModal();}
function bindCompanyRows(){const d=state.data;$$('[data-edit]').forEach(b=>b.onclick=()=>companyModal(d.companies.find(x=>x.id===b.dataset.edit)));$$('[data-admins]').forEach(b=>b.onclick=()=>adminsModal(d.companies.find(x=>x.id===b.dataset.admins)));$$('[data-del]').forEach(b=>b.onclick=()=>confirmDel('Këtë firmë me të gjitha të dhënat e saj',async()=>{try{await api('/companies/'+b.dataset.del,{method:'DELETE'});toast('Firma u fshi.');await load();}catch(x){toast(x.message);}}));}

/* ----- Company administrators modal (superadmin: add/edit/remove admins of an existing firm) ----- */
async function adminsModal(co){
 openModal(`<div class="modal-head"><h3>Administratorët — ${esc(co.displayName||co.name)}</h3><button class="x" onclick="closeModal()">✕</button></div><div class="modal-body"><div id="adminsList" class="table-wrap"><p class="empty">Duke ngarkuar…</p></div><div class="modal-foot"><button type="button" class="btn btn-secondary" onclick="closeModal()">Mbyll</button><button class="btn btn-primary" id="newAdmin">+ Administrator i ri</button></div></div>`,true);
 $('#newAdmin').onclick=()=>adminEditModal(co,null);
 await refreshAdminsList(co);
}
async function refreshAdminsList(co){
 const box=$('#adminsList');if(!box)return;
 try{
  const{admins}=await api('/companies/'+co.id+'/admins');
  box.innerHTML=admins.length?`<table><thead><tr><th>Emri</th><th>Përdoruesi</th><th>Statusi</th><th class="ta-r">Veprime</th></tr></thead><tbody>${admins.map(a=>`<tr><td><strong>${esc(a.name)}</strong></td><td class="mono">${esc(a.username)}</td><td>${a.status==='Aktiv'?'<span class="badge ok">Aktiv</span>':'<span class="badge bad">Joaktiv</span>'}</td><td class="ta-r"><div class="rowbtns"><button class="mini" data-aedit="${a.id}" title="Edito">✎</button><button class="mini danger" data-adel="${a.id}" title="Fshi">✕</button></div></td></tr>`).join('')}</tbody></table>`:`<p class="empty">Kjo firmë nuk ka ende asnjë administrator.</p>`;
  $$('[data-aedit]',box).forEach(b=>b.onclick=()=>adminEditModal(co,admins.find(a=>a.id===b.dataset.aedit)));
  $$('[data-adel]',box).forEach(b=>b.onclick=()=>confirmDel('Këtë administrator',async()=>{try{await api('/companies/'+co.id+'/admins/'+b.dataset.adel,{method:'DELETE'});toast('Administratori u fshi.');await adminsModal(co);}catch(x){toast(x.message);}}));
 }catch(x){box.innerHTML=`<p class="empty">${esc(x.message)}</p>`;}
}
function adminEditModal(co,a){
 const edit=!!a;
 openModal(`<div class="modal-head"><h3>${edit?'Edito administratorin':'Administrator i ri'}</h3><button class="x" onclick="closeModal()">✕</button></div><form id="aForm" class="modal-body"><div class="field"><label>Emri *</label><input class="input" id="an" value="${edit?esc(a.name):''}" required></div><div class="grid-2"><div class="field"><label>Përdoruesi *</label><input class="input" id="au" value="${edit?esc(a.username):''}" required></div><div class="field"><label>${edit?'Fjalëkalim i ri (opsional)':'Fjalëkalimi *'}</label><input class="input" id="ap" type="text" ${edit?'':'required'}></div></div>${edit?`<div class="field"><label>Statusi</label><select class="input" id="as"><option ${a.status==='Aktiv'?'selected':''}>Aktiv</option><option ${a.status!=='Aktiv'?'selected':''}>Joaktiv</option></select></div>`:''}<div class="modal-foot"><button type="button" class="btn btn-secondary" onclick="closeModal()">Anulo</button><button class="btn btn-primary">Ruaj</button></div></form>`,true);
 $('#aForm').onsubmit=async e=>{e.preventDefault();try{const body={name:$('#an').value.trim(),username:$('#au').value.trim()};if($('#ap').value)body.password=$('#ap').value;if(edit)body.status=$('#as').value;if(!edit&&!body.password)return toast('Fjalëkalimi kërkohet.');await api(edit?'/companies/'+co.id+'/admins/'+a.id:'/companies/'+co.id+'/admins',{method:edit?'PUT':'POST',body:JSON.stringify(body)});toast('U ruajt.');await adminsModal(co);await load();}catch(x){toast(x.message);}};
}
function companyModal(co){const edit=!!co;openModal(`<div class="modal-head"><h3>${edit?'Edito firmën':'Firmë e re'}</h3><button class="x" onclick="closeModal()">✕</button></div><form id="coForm" class="modal-body"><div class="grid-2"><div class="field"><label>Emri ligjor *</label><input class="input" id="coName" value="${edit?esc(co.name):''}" placeholder="p.sh. Nova Travel L.L.C." required></div><div class="field"><label>Emri i shfaqur</label><input class="input" id="coDisp" value="${edit?esc(co.displayName||''):''}" placeholder="p.sh. Nova"></div></div><div class="field"><label>Subdomaini *</label><div class="domain-input"><input class="input" id="coSub" value="${edit?esc(co.subdomain||''):''}" placeholder="nova" required><span id="domPrev">.datapos.pro</span></div></div><div class="grid-2"><div class="field"><label>Telefoni</label><input class="input" id="coPhone" value="${edit?esc(co.phone||''):''}"></div><div class="field"><label>Email</label><input class="input" id="coEmail" value="${edit?esc(co.email||''):''}"></div></div><div class="grid-2"><div class="field"><label>Adresa</label><input class="input" id="coAddr" value="${edit?esc(co.address||''):''}"></div><div class="field"><label>NUI</label><input class="input" id="coNui" value="${edit?esc(co.nui||''):''}"></div></div>${edit?`<div class="field"><label>Statusi</label><select class="input" id="coStatus"><option${co.status==='Aktiv'?' selected':''}>Aktiv</option><option${co.status==='Joaktiv'?' selected':''}>Joaktiv</option></select></div>`:`<div class="grid-2"><div class="field"><label>Emri i administratorit *</label><input class="input" id="coAdminName" required></div><div class="field"><label>Përdoruesi i adminit *</label><input class="input" id="coAdminUser" required></div></div><div class="field"><label>Fjalëkalimi i adminit *</label><input class="input" id="coAdminPass" type="text" required></div>`}<div class="modal-foot"><button type="button" class="btn btn-secondary" onclick="closeModal()">Anulo</button><button class="btn btn-primary">${edit?'Ruaj ndryshimet':'Krijo firmën'}</button></div></form>`,true);
 const sub=$('#coSub'),name=$('#coName');const prev=()=>{$('#domPrev').textContent=(slugify(sub.value||name.value||'')||'firma')+'.datapos.pro';};name.oninput=()=>{if(!sub.value)prev();};sub.oninput=prev;prev();
 $('#coForm').onsubmit=async e=>{e.preventDefault();const body={name:name.value.trim(),displayName:$('#coDisp').value.trim(),subdomain:sub.value.trim(),phone:$('#coPhone').value.trim(),email:$('#coEmail').value.trim(),address:$('#coAddr').value.trim(),nui:$('#coNui').value.trim()};try{if(edit){body.status=$('#coStatus').value;await api('/companies/'+co.id,{method:'PUT',body:JSON.stringify(body)});toast('Firma u përditësua.');}else{body.adminName=$('#coAdminName').value.trim();body.adminUsername=$('#coAdminUser').value.trim();body.adminPassword=$('#coAdminPass').value;await api('/companies',{method:'POST',body:JSON.stringify(body)});toast('Firma u krijua.');}closeModal();await load();}catch(x){toast(x.message);}};}
function confirmDel(what,fn){openModal(`<div class="modal-head"><h3>Konfirmo fshirjen</h3><button class="x" onclick="closeModal()">✕</button></div><div class="modal-body"><p>Jeni i sigurt që doni të fshini ${what.toLowerCase()}? Ky veprim nuk kthehet.</p><div class="modal-foot"><button class="btn btn-secondary" onclick="closeModal()">Anulo</button><button class="btn btn-danger" id="okDel">Po, fshi</button></div></div>`);$('#okDel').onclick=async()=>{closeModal();await fn();};}
window.closeModal=closeModal;

/* ---------------- BOOT ---------------- */
(async()=>{try{state.branding=await api('/branding'+(qp('firm')?`?firm=${encodeURIComponent(qp('firm'))}`:''));}catch{}try{const d=await api('/me');state.me=d.user;await load();}catch{renderLogin();}})();
